337:     /**
338:      * Spatial 2D navigation algorithm between navigable items
339:      */
340:     navigateSpatial: function (direction, event) {
341:       var current = this.state.focusedElement;
342:       if (!current) {
343:         this.setInitialFocus();
344:         return;
345:       }
346: 
347:       var currentRect = current.getBoundingClientRect();
348:       var activeView = document.getElementById('view-' + this.state.currentView);
349:       var navCandidates = [];
350: 
351:       // Include header nav items if header is visible
352:       var header = document.querySelector('.app-header');
353:       if (header && !header.classList.contains('header-hidden')) {
354:         var headerNavs = header.querySelectorAll('[data-nav="true"]');
355:         for (var h = 0; h < headerNavs.length; h++) {
356:           navCandidates.push(headerNavs[h]);
357:         }
358:       }
359: 
360:       // Include view nav items
361:       if (activeView) {
362:         var viewNavs = activeView.querySelectorAll('[data-nav="true"]');
363:         for (var v = 0; v < viewNavs.length; v++) {
364:           navCandidates.push(viewNavs[v]);
365:         }
366:       }
367: 
368:       var bestCandidate = null;
369:       var minDistance = Infinity;
370: 
371:       for (var i = 0; i < navCandidates.length; i++) {
372:         var cand = navCandidates[i];
373:         if (cand === current) continue;
374: 
375:         var candRect = cand.getBoundingClientRect();
376:         if (candRect.width === 0 || candRect.height === 0) continue;
377: 
378:         var isDirectional = false;
379:         var primaryDiff = 0;
380:         var secondaryDiff = 0;
381: 
382:         var currentCenterX = currentRect.left + currentRect.width / 2;
383:         var currentCenterY = currentRect.top + currentRect.height / 2;
384:         var candCenterX = candRect.left + candRect.width / 2;
385:         var candCenterY = candRect.top + candRect.height / 2;
386: 
387:         if (direction === 'ArrowRight' && candRect.left >= currentRect.right - 10) {
388:           isDirectional = true;
389:           primaryDiff = candRect.left - currentRect.right;
390:           secondaryDiff = Math.abs(candCenterY - currentCenterY);
391:         } else if (direction === 'ArrowLeft' && candRect.right <= currentRect.left + 10) {
392:           isDirectional = true;
393:           primaryDiff = currentRect.left - candRect.right;
394:           secondaryDiff = Math.abs(candCenterY - currentCenterY);
395:         } else if (direction === 'ArrowDown' && candRect.top >= currentRect.bottom - 10) {
396:           isDirectional = true;
397:           primaryDiff = candRect.top - currentRect.bottom;
398:           secondaryDiff = Math.abs(candCenterX - currentCenterX);
399:         } else if (direction === 'ArrowUp' && candRect.bottom <= currentRect.top + 10) {
400:           isDirectional = true;
401:           primaryDiff = currentRect.top - candRect.bottom;
402:           secondaryDiff = Math.abs(candCenterX - currentCenterX);
403:         }
404: 
405:         if (isDirectional) {
406:           // Weight primary direction over secondary deviation
407:           var distance = primaryDiff * 1.0 + secondaryDiff * 2.2;
408:           if (distance < minDistance) {
409:             minDistance = distance;
410:             bestCandidate = cand;
411:           }
412:         }
413:       }
414: 
415:       if (bestCandidate) {
416:         event.preventDefault();
417:         this.setFocus(bestCandidate);
418:       }
