/**
 * tests/adversarial-m2.js - Empirical Adversarial Test Harness for Milestone 2
 * 
 * Conducts stress tests, boundary tests, and security audits on:
 * 1. View routing: Valid routes, invalid hash routes (#unknown-999), rapid hash switching, async focus race conditions.
 * 2. DOM robustness: Missing containers, partial structures, bare elements, scrollpane resilience.
 * 3. XSS & Special Characters: Script injection, event handlers, tag breakout, unicode fuzzing, search type safety.
 * 4. Navigation state & Remote Control: Back key hierarchy, details infinite loop traps, init idempotency, spatial event safety.
 */

const fs = require('fs');
const path = require('path');

// Resolve JSDOM across available environments
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      throw new Error('JSDOM module could not be resolved: ' + e.message);
    }
  }
}

// ANSI Terminal Colors
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m',
};

let totalAdversarialTests = 0;
let passedAdversarialTests = 0;
let failedAdversarialTests = 0;
const testLogs = [];

function assert(condition, message) {
  if (!condition) {
    throw new Error(message || 'Adversarial assertion failed');
  }
}

async function runAdversarialTest(category, name, testFn) {
  totalAdversarialTests++;
  const testId = totalAdversarialTests;
  const startTime = Date.now();
  process.stdout.write(`  [Test ${testId.toString().padStart(2, '0')}] [${category}] ${name} ... `);
  try {
    await testFn();
    const duration = Date.now() - startTime;
    console.log(`${C.green}${C.bold}✔ PASS${C.reset} ${C.gray}(${duration}ms)${C.reset}`);
    passedAdversarialTests++;
    testLogs.push({ id: testId, category, name, pass: true, duration });
  } catch (err) {
    const duration = Date.now() - startTime;
    console.log(`${C.red}${C.bold}✖ FAIL${C.reset} ${C.gray}(${duration}ms)${C.reset}`);
    console.error(`      ${C.red}Defect: ${err.message}${C.reset}`);
    failedAdversarialTests++;
    testLogs.push({ id: testId, category, name, pass: false, error: err.message, duration });
  }
}

/**
 * Helper to create a fresh DOM window with app loaded
 */
function createTestDom(initialUrl = 'http://localhost/#home') {
  const htmlPath = path.resolve(__dirname, '../app/index.html');
  const configPath = path.resolve(__dirname, '../app/js/config.js');
  const appPath = path.resolve(__dirname, '../app/js/app.js');

  const html = fs.readFileSync(htmlPath, 'utf8');
  const dom = new JSDOM(html, {
    url: initialUrl,
    runScripts: 'outside-only'
  });
  const { window } = dom;

  // Polyfill Element.prototype.scrollIntoView for headless environment
  if (!window.Element.prototype.scrollIntoView) {
    window.Element.prototype.scrollIntoView = function () {};
  }

  const configCode = fs.readFileSync(configPath, 'utf8');
  const appCode = fs.readFileSync(appPath, 'utf8');

  window.eval(configCode);
  window.eval(appCode);

  return { dom, window, app: window.CinejoyApp };
}

/**
 * Suite 1: View Router & Hash Transitions
 */
async function runRouterSuite() {
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 1: View Router & Hash Transitions${C.reset}`);

  // Test 1: Bootstrap initial routing with valid hash
  await runAdversarialTest('ROUTER', 'Bootstrap initial routing with valid hashes (#movies, #series, etc.)', async () => {
    const testViews = ['movies', 'series', 'search', 'details', 'player'];
    for (const v of testViews) {
      const { window, app } = createTestDom(`http://localhost/#${v}`);
      app.init();
      assert(app.state.currentView === v, `Expected currentView to be ${v}, got ${app.state.currentView}`);
      const activeEl = window.document.querySelector('.view.active');
      assert(activeEl && activeEl.id === `view-${v}`, `Expected #view-${v} to have active class`);
    }
  });

  // Test 2: Bootstrap initial routing with invalid hash (#unknown-route-999, etc.)
  await runAdversarialTest('ROUTER', 'Bootstrap initial routing fallback on invalid hashes (#unknown-route-999, #admin)', async () => {
    const invalidHashes = ['#unknown-route-999', '#admin', '#foobar/baz', '#', '##', '#undefined', '#null'];
    for (const h of invalidHashes) {
      const { window, app } = createTestDom(`http://localhost/${h}`);
      app.init();
      assert(app.state.currentView === 'home', `Expected fallback to 'home' for hash ${h}, got ${app.state.currentView}`);
      const activeEl = window.document.querySelector('.view.active');
      assert(activeEl && activeEl.id === 'view-home', `Expected #view-home to be active for hash ${h}`);
    }
  });

  // Test 3: Runtime hashchange transitions across all valid views
  await runAdversarialTest('ROUTER', 'Runtime hashchange transitions across all 6 views', async () => {
    const { window, app } = createTestDom();
    app.init();

    const sequence = ['movies', 'series', 'search', 'details', 'player', 'home'];
    for (const target of sequence) {
      window.location.hash = '#' + target;
      window.dispatchEvent(new window.HashChangeEvent('hashchange'));
      assert(app.state.currentView === target, `Expected switch to ${target}, got ${app.state.currentView}`);
      const activeView = window.document.querySelector('.view.active');
      assert(activeView && activeView.id === `view-${target}`, `Expected #view-${target} to be active`);
    }
  });

  // Test 4: Runtime hashchange with malformed/unknown hashes
  await runAdversarialTest('ROUTER', 'Runtime hashchange with malformed/unknown hashes preserves state without crashing', async () => {
    const { window, app } = createTestDom('http://localhost/#series');
    app.init();
    assert(app.state.currentView === 'series');

    const weirdHashes = ['#invalid-404-not-found', '#!/action', '#__proto__', '###', '#', '#?query=123'];
    for (const h of weirdHashes) {
      window.location.hash = h;
      window.dispatchEvent(new window.HashChangeEvent('hashchange'));
      // State should remain safe and not throw
      assert(app.views.indexOf(app.state.currentView) !== -1, `State corrupted to invalid view: ${app.state.currentView}`);
    }
  });

  // Test 5: Direct switchView calls with invalid types
  await runAdversarialTest('ROUTER', 'Direct switchView with invalid types (null, undefined, numbers, objects, proto)', async () => {
    const { app } = createTestDom();
    app.init();
    const initialView = app.state.currentView;

    const invalidInputs = [null, undefined, 12345, true, false, {}, [], '__proto__', 'constructor', 'toString'];
    for (const inv of invalidInputs) {
      app.switchView(inv);
      assert(app.state.currentView === initialView, `switchView should reject invalid input ${inv}, but state changed to ${app.state.currentView}`);
    }
  });

  // Test 6: Rapid hash switching stress: 60 rapid switches
  await runAdversarialTest('ROUTER', 'Rapid hash switching stress (60 switches in tight sequence)', async () => {
    const { window, app } = createTestDom();
    app.init();

    const views = ['home', 'movies', 'series', 'search', 'details', 'player'];
    for (let i = 0; i < 60; i++) {
      const target = views[i % views.length];
      app.switchView(target);
      assert(app.state.currentView === target);
      const activeViews = window.document.querySelectorAll('.view.active');
      assert(activeViews.length === 1, `Expected exactly 1 active view during rapid switch ${i}, found ${activeViews.length}`);
      assert(activeViews[0].id === `view-${target}`);
    }
  });

  // Test 7: Async focus race condition under rapid hash switching
  await runAdversarialTest('ROUTER', 'Async focus race condition: pending timer must not focus inactive view', async () => {
    const { window, app } = createTestDom();
    app.init();

    // Step A: Switch to 'movies' (schedules focusFirstElementInView('movies') in 50ms)
    app.switchView('movies');

    // Step B: Before 50ms (at 25ms), switch to 'series'
    await new Promise((resolve) => setTimeout(resolve, 25));
    app.switchView('series');

    // Step C: Wait until t=65ms (when the 'movies' timer has fired, but 'series' timer is still pending)
    await new Promise((resolve) => setTimeout(resolve, 40));

    // DEFECT CHECK:
    // If focusFirstElementInView lacks a view check, app.state.focusedElement is now inside #view-movies!
    const focusedEl = app.state.focusedElement;
    assert(focusedEl, 'A focused element must exist');

    const inMovies = window.document.getElementById('view-movies').contains(focusedEl);
    const inSeries = window.document.getElementById('view-series').contains(focusedEl);
    const inHeader = window.document.querySelector('.app-header').contains(focusedEl);

    if (inMovies) {
      throw new Error(`RACE CONDITION DETECTED: Focused element is inside inactive view-movies while currentView is ${app.state.currentView}!`);
    }
    assert(inSeries || inHeader, `Focused element must be in active view (series) or header, but was: ${focusedEl.className}`);
  });

  // Test 8: Focus retention under view switch delay (manual user focus must not be stolen)
  await runAdversarialTest('ROUTER', 'Focus retention: pending switch timer must not steal user manual focus', async () => {
    const { window, app } = createTestDom();
    app.init();

    app.switchView('series');

    // At 20ms, user presses D-pad and selects 4th card
    await new Promise((resolve) => setTimeout(resolve, 20));
    const cards = window.document.getElementById('view-series').querySelectorAll('.card-poster');
    const userSelectedCard = cards[3];
    assert(userSelectedCard, 'Expected 4th card in series grid');
    app.setFocus(userSelectedCard);

    // At 80ms (after the 50ms timer has fired)
    await new Promise((resolve) => setTimeout(resolve, 60));

    // DEFECT CHECK: Did the 50ms timer overwrite userSelectedCard back to first element?
    if (app.state.focusedElement !== userSelectedCard) {
      throw new Error(`FOCUS HIJACK DETECTED: User manual focus was overwritten by switchView timeout! Expected card "${userSelectedCard.getAttribute('data-title')}", got: ${app.state.focusedElement.className}`);
    }
  });
}

