/**
 * Suite 3: XSS & Special Characters Injection Simulation
 */
async function runXssSuite() {
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 3: XSS & Special Characters Injection Simulation${C.reset}`);

  // Test 17: Script injection in title
  await runAdversarialTest('XSS', 'Script injection simulation in title (<script>alert(1)</script>)', async () => {
    const { window, app } = createTestDom();
    app.init();

    const xssPayload = '<script id="xss-test-payload">window.__XSS_PWNED = true;</script>';
    app.openDetails({ title: xssPayload, year: '2026', rating: '9.0' });

    assert(!window.__XSS_PWNED, 'XSS executed! window.__XSS_PWNED should be undefined');
    assert(!window.document.getElementById('xss-test-payload'), 'Script tag was injected into DOM tree!');

    const titleEl = window.document.getElementById('details-title');
    assert(titleEl.textContent === xssPayload, 'textContent should contain payload literally');
    assert(titleEl.innerHTML.includes('&lt;script'), 'innerHTML must be properly entity-escaped');
  });

  // Test 18: Event handler injection in metadata
  await runAdversarialTest('XSS', 'Event handler injection simulation (<img src=x onerror=...>)', async () => {
    const { window, app } = createTestDom();
    app.init();

    const imgPayload = '<img src=x onerror="window.__IMG_PWNED=true">';
    app.openDetails({ title: 'Safe Title', year: imgPayload, rating: '8.0' });

    assert(!window.__IMG_PWNED, 'Image onerror handler executed!');
    const yearEl = window.document.getElementById('details-meta-year');
    assert(yearEl.textContent === imgPayload);
    assert(yearEl.innerHTML.includes('&lt;img'), 'Image tag must be entity-escaped');
  });

  // Test 19: Tag breakout injection in ratings
  await runAdversarialTest('XSS', 'Tag breakout markup injection ("><b id="breakout">)', async () => {
    const { window, app } = createTestDom();
    app.init();

    const breakout = '"><b id="breakout-element">injected</b>';
    app.openDetails({ title: 'Safe', year: '2024', rating: breakout });

    assert(!window.document.getElementById('breakout-element'), 'Breakout HTML markup created DOM elements!');
    const ratingEl = window.document.getElementById('details-meta-rating');
    assert(ratingEl.innerHTML.includes('&lt;b id='), 'Markup must be escaped in innerHTML');
  });

  // Test 20: High-stress unicode and RTL override strings
  await runAdversarialTest('XSS', 'Unicode stress, emojis, zero-width chars, and 10,000-char strings', async () => {
    const { window, app } = createTestDom();
    app.init();

    const hugeUnicode = '🎬 🍿 \u202E \u200B \uFEFF \u0000 \t \n ' + 'A'.repeat(10000);
    app.openDetails({ title: hugeUnicode, year: '2024', rating: '8.5' });

    const titleEl = window.document.getElementById('details-title');
    assert(titleEl.textContent === hugeUnicode, 'Large unicode text was corrupted');
  });

  // Test 21: Special character injection in search query
  await runAdversarialTest('XSS', 'Special character injection in search input (& < > " \' / \\ % $ ; * ( ))', async () => {
    const { window, app } = createTestDom('http://localhost/#search');
    app.init();

    const specialQuery = '<script> & " \' / \\ % $ ; * ( ) { }';
    app.state.searchQuery = specialQuery;
    const inputDisplay = window.document.getElementById('search-query-text');
    inputDisplay.textContent = app.state.searchQuery;
    app.updateSearchResults(app.state.searchQuery);

    assert(inputDisplay.textContent === specialQuery);
    assert(inputDisplay.innerHTML.includes('&lt;script&gt;'));
  });

  // Test 22: Virtual keyboard key injection
  await runAdversarialTest('XSS', 'Virtual keyboard key injection with custom payload in data-key', async () => {
    const { window, app } = createTestDom('http://localhost/#search');
    app.init();

    const maliciousKey = window.document.createElement('button');
    maliciousKey.className = 'key-btn';
    maliciousKey.setAttribute('data-key', '<svg onload=alert(1)>');
    window.document.querySelector('.tv-keyboard-container').appendChild(maliciousKey);

    maliciousKey.dispatchEvent(new window.MouseEvent('click', { bubbles: true }));
    const inputDisplay = window.document.getElementById('search-query-text');
    assert(inputDisplay.textContent.includes('<svg onload=alert(1)>'));
    assert(inputDisplay.innerHTML.includes('&lt;svg'));
  });

  // Test 23: Type fuzzing on updateSearchResults
  await runAdversarialTest('XSS', 'Type fuzzing on updateSearchResults (numbers, booleans, objects, arrays)', async () => {
    const { app } = createTestDom('http://localhost/#search');
    app.init();

    const fuzzValues = [12345, true, false, { search: 'dune' }, ['action', 'sci-fi']];
    for (const val of fuzzValues) {
      try {
        app.updateSearchResults(val);
      } catch (err) {
        throw new Error(`CRASH on updateSearchResults(${typeof val}): ${err.message}`);
      }
    }
  });

  // Test 24: Codebase-wide DOM sink security audit
  await runAdversarialTest('XSS', 'Audit codebase for dangerous DOM sinks (innerHTML, outerHTML, document.write, eval)', async () => {
    const appDir = path.resolve(__dirname, '../app');
    const files = ['index.html', 'js/app.js', 'js/config.js'];

    for (const file of files) {
      const content = fs.readFileSync(path.join(appDir, file), 'utf8');
      assert(!/\.innerHTML\s*=/.test(content), `Dangerous assignment to .innerHTML found in app/${file}`);
      assert(!/\.outerHTML\s*=/.test(content), `Dangerous assignment to .outerHTML found in app/${file}`);
      assert(!/document\.write\(/.test(content), `Dangerous document.write call found in app/${file}`);
      assert(!/window\.eval\(/.test(content), `Dangerous eval call found in app/${file}`);
    }
  });
}

/**
 * Suite 4: Navigation State & Remote Control Robustness
 */
async function runNavStateSuite() {
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 4: Navigation State & Remote Control Robustness${C.reset}`);

  // Test 25: Programmatic navigateSpatial without event object
  await runAdversarialTest('NAV', 'Programmatic navigateSpatial without event object (defensive preventDefault check)', async () => {
    const { window, app } = createTestDom();
    app.init();

    const navs = window.document.querySelectorAll('[data-nav="true"]');
    navs[0].getBoundingClientRect = () => ({ top: 10, bottom: 40, left: 10, right: 100, width: 90, height: 30 });
    navs[1].getBoundingClientRect = () => ({ top: 10, bottom: 40, left: 120, right: 200, width: 80, height: 30 });
    app.setFocus(navs[0]);

    try {
      app.navigateSpatial('ArrowRight'); // No event passed
    } catch (err) {
      throw new Error(`CRASH on navigateSpatial without event: ${err.message}`);
    }
  });

  // Test 26: Idempotency of CinejoyApp.init()
  await runAdversarialTest('NAV', 'Idempotency of CinejoyApp.init() (listeners must not duplicate)', async () => {
    const { window, app } = createTestDom('http://localhost/#search');
    app.init();
    app.init(); // Second initialization

    // Press 'A' key on keyboard
    const keyA = window.document.querySelector('[data-key="A"]');
    keyA.dispatchEvent(new window.MouseEvent('click', { bubbles: true }));

    if (app.state.searchQuery === 'AA') {
      throw new Error(`DUPLICATE LISTENERS DETECTED: Single keypress of "A" produced "${app.state.searchQuery}" because init() is not idempotent!`);
    }
    assert(app.state.searchQuery === 'A', `Expected search query "A", got "${app.state.searchQuery}"`);
  });

  // Test 27: Hierarchical Back navigation from player view
  await runAdversarialTest('NAV', 'Hierarchical Back navigation: exitPlayer returns to previous view', async () => {
    const { app } = createTestDom('http://localhost/#movies');
    app.init();
    assert(app.state.currentView === 'movies');

    app.switchView('player');
    assert(app.state.currentView === 'player');
    assert(app.state.previousView === 'movies');

    app.exitPlayer();
    assert(app.state.currentView === 'movies', `Expected return to 'movies', got ${app.state.currentView}`);
  });

  // Test 28: Hierarchical Back navigation loop prevention in details view
  await runAdversarialTest('NAV', 'Hierarchical Back navigation: details -> details must not lock user in infinite loop', async () => {
    const { app } = createTestDom('http://localhost/#home');
    app.init();

    // User opens details for Item 1
    app.openDetails({ title: 'Item 1', year: '2024', rating: '8.0' });
    assert(app.state.currentView === 'details');
    assert(app.state.previousView === 'home');

    // While in details, user opens details for related Item 2
    app.openDetails({ title: 'Item 2', year: '2024', rating: '8.5' });
    assert(app.state.currentView === 'details');
    // State now has previousView === 'details'

    // Press Back key
    app.handleBackNavigation();

    // DEFECT CHECK: Did Back key trap user in 'details'?
    if (app.state.currentView === 'details') {
      throw new Error(`INFINITE LOOP TRAP DETECTED: Back key pressed on details resulted in currentView='details'! User cannot escape details view with TV remote back key!`);
    }
    assert(app.state.currentView === 'home', `Expected Back key to return to 'home', got ${app.state.currentView}`);
  });

  // Test 29: D-pad navigation with disconnected or zero-dimension active focus element
  await runAdversarialTest('NAV', 'D-pad navigation resilience when focused element is disconnected from DOM', async () => {
    const { window, app } = createTestDom();
    app.init();

    const tempBtn = window.document.createElement('button');
    tempBtn.setAttribute('data-nav', 'true');
    window.document.body.appendChild(tempBtn);
    app.setFocus(tempBtn);

    // Remove element from DOM
    tempBtn.remove();

    // Attempt arrow key navigation
    const mockEvent = { preventDefault: () => {} };
    app.navigateSpatial('ArrowDown', mockEvent);
    // Should not crash, and should fall back gracefully
    assert(app.state.focusedElement !== tempBtn, 'Focus was not recovered after element removal');
  });
}

